/* BankAuctions.ai · assignment cards and task detail, shared by the website console and the Android app */
(function(){
var FV=window.FV,BA=window.BA,esc=BA.esc;
function tel(p){return '<a href="tel:+91'+esc(p)+'" onclick="event.stopPropagation()">'+esc(p.slice(0,5)+' '+p.slice(5))+'</a>'}
FV.tel=tel;
FV.slaText=function(a,s){s=s||FV.sla(a);var now=Date.now();if(s.level==='done')return s.label;
 if(s.reasons.length){return s.reasons.map(function(r){return r.txt+' · '+FV.left(r.over)+' late'}).join(' · ')}
 return s.next?s.next.label+' '+FV.when(s.next.due)+' · '+FV.left(s.next.due-now)+' left':''};
FV.chip=function(s){var c=FV.COL[s.level];return '<span class="fsl" style="background:'+c.bg+';color:'+c.tx+'">'+(s.ret&&s.level!=='overdue'?'Returned':c.lb)+'</span>'};
/* one row in the queue: property, bank branch, contact, who shows it, time to visit, deadline */
FV.card=function(id,a,sel){var p=FV.property(id),s=FV.sla(a),c=FV.COL[s.level],b=a.br;
 return '<div class="fcd'+(sel?' sel':'')+'" data-task="'+id+'" style="border-left-color:'+c.bd+';background:'+(s.level==='ok'?'#fff':c.bg)+'"><div class="ft2"><b>'+esc(p.short)+' · '+esc(p.loc)+'</b>'+FV.chip(s)+'</div>'+
 '<div class="fm2">'+esc(BA.CL[p.cat])+' · '+esc(p.size)+' · '+BA.inr(p.reserve)+' reserve · '+esc(FV.cl(p.city))+(p.premium?' · <b>PREMIUM</b>':'')+'<br>'+
 '<b>'+esc(b.name)+'</b> · '+esc(b.loc)+'<br>Branch contact: <b>'+esc(b.officer)+'</b> '+tel(b.officerPhone)+'<br>Will show the property: <b>'+esc(b.showName)+'</b> '+tel(b.showPhone)+'<br>'+
 (a.sched?'Visit booked: <b>'+esc(FV.dshort(a.sched.d))+', '+esc(a.sched.t)+'</b>':'Bank suggests: <b>'+esc(FV.dshort(b.visit.d))+', '+esc(b.visit.t)+'</b>')+'</div>'+
 '<div class="fm2" style="color:'+c.tx+';font-weight:700;margin-top:6px">'+esc(FV.stage(a))+(FV.slaText(a,s)?' · '+esc(FV.slaText(a,s)):'')+'</div></div>'};
FV.timeline=function(a){var steps=[['Assigned',true],['Accepted',!!a.ack],['Scheduled',!!a.sched],['Submitted',!!a.sub],['Approved',a.fin==='approved']];return '<div class="ftl">'+steps.map(function(x){return '<i class="'+(x[1]?'y':'')+'">'+x[0]+'</i>'}).join('')+'</div>'};
FV.taskHtml=function(id){var p=FV.property(id),a=FV.asg()[id],s=FV.sla(a),c=FV.COL[s.level],b=a.br,e=FV.get(a.eng),m=e&&e.manager?FV.get(e.manager):null,now=Date.now();
 var h='<div class="fvs"><div class="fvh"><b style="font-size:18px">'+esc(p.title)+'</b></div><p class="fvp" style="margin-top:0">'+esc(p.bank)+' · '+esc(p.loc)+', '+esc(FV.cl(p.city))+' · '+esc(p.pin)+' · Property '+p.id+'</p>'+
 '<div class="fvg2" style="font-size:14px"><div><small style="color:#6b6b75">Reserve</small><br><b>'+BA.inr(p.reserve)+'</b></div><div><small style="color:#6b6b75">Auction</small><br><b>'+esc(p.auction_full)+'</b></div><div><small style="color:#6b6b75">Possession per bank</small><br><b>'+esc(p.poss)+'</b></div><div><small style="color:#6b6b75">Size per notice</small><br><b>'+esc(p.size)+'</b></div></div>'+
 '<div style="margin-top:12px;border-radius:12px;padding:10px 12px;background:'+c.bg+';color:'+c.tx+';border-left:5px solid '+c.bd+'"><b>'+esc(FV.stage(a))+'</b>'+(FV.slaText(a,s)?'<br>'+esc(FV.slaText(a,s)):'')+'</div>'+FV.timeline(a)+
 '<p class="fvp" style="margin:6px 0 0">Assigned '+esc(FV.when(a.at))+'. Accept within 18 hours and finish the visit within 48 hours. Late items are shown to '+(m?esc(m.name)+', your reporting manager, and ':'your reporting manager and ')+'to Admin and Leadership.</p></div>';
 h+='<div class="fvs"><div class="fvh"><b>Bank branch and who to meet</b></div><div class="brc"><b>'+esc(b.name)+'</b><br>'+esc(b.loc)+'<br><br>Branch contact: <b>'+esc(b.officer)+'</b>, '+esc(b.officerRole)+' · '+tel(b.officerPhone)+'<br>Will show you the property: <b>'+esc(b.showName)+'</b> · '+tel(b.showPhone)+'<br>Branch hours for visits: '+esc(b.window)+'<br>Time to visit given by the bank: <b>'+esc(FV.dshort(b.visit.d))+', '+esc(b.visit.t)+'</b></div></div>';
 return h};
/* accept and schedule buttons. Returns html; call FV.taskWire afterwards */
FV.actionsHtml=function(id){var a=FV.asg()[id];if(a.sub||a.fin)return '';var h='<div class="fvs" data-acts="1">';
 if(a.ret)return '';
 if(!a.ack)h+='<div class="fvh"><b>Step 1 · Accept this visit</b></div><p class="fvp">Accepting tells the bank branch and your manager that you are taking this visit.</p><button class="fbn" data-accept="'+id+'" style="width:100%">Accept assignment</button>';
 else{var days=[0,1,2,3,4,5].map(function(i){return Date.now()+i*864e5}).filter(function(x){return new Date(x).getDay()!==0}).slice(0,5).map(function(x){return FV.ymd(x)}),bk=a.sched||a.br.visit,sd=days.indexOf(bk.d)>-1?bk.d:days[1],times=['9:00 am','10:30 am','11:30 am','2:30 pm','3:30 pm','5:00 pm'],st=times.indexOf(bk.t)>-1?bk.t:'10:30 am';
  h+='<div class="fvh"><b>'+(a.sched?'Your visit is booked':'Step 2 · Schedule the visit')+'</b></div><p class="fvp">'+(a.sched?'You can change the time if the bank officer agrees.':'Pick a time that suits the person who will show you the property. The branch will be told through the portal.')+'</p><div class="fvg2"><label class="fl">Date<select class="fin" id="fvd">'+days.map(function(x){return '<option value="'+x+'"'+(x===sd?' selected':'')+'>'+esc(FV.dshort(x))+'</option>'}).join('')+'</select></label><label class="fl">Time<select class="fin" id="fvt">'+times.map(function(x){return '<option'+(x===st?' selected':'')+'>'+x+'</option>'}).join('')+'</select></label></div><button class="fbn" data-sched="'+id+'" style="width:100%">'+(a.sched?'Change visit time':'Confirm visit time')+'</button>'}
 return h+'</div>'};
FV.taskWire=function(root,onChange){root.addEventListener('click',function(e){var b=e.target.closest('button');if(!b)return;
 if(b.dataset.accept){FV.accept(b.dataset.accept);BA.toast('Accepted. Now choose a visit time.');onChange&&onChange()}
 else if(b.dataset.sched){var id=b.dataset.sched,d=root.querySelector('#fvd').value,t=root.querySelector('#fvt').value;FV.schedule(id,d,t);BA.toast('Visit booked for '+FV.dshort(d)+', '+t);onChange&&onChange()}})};

/* ---------- manager and leadership views of the field team ---------- */
FV.escRows=function(list,withMgr){var esc=BA.esc;return list.map(function(x){var mg=FV.get(x.e.manager);return '<tr><td><b>'+esc(x.p.short)+' · '+esc(x.p.loc)+'</b><br><small style="color:var(--mute)">'+x.id+' · '+esc(FV.cl(x.p.city))+'</small></td><td>'+esc(x.e.name)+'<br><small>'+FV.tel(x.e.phone)+'</small></td>'+(withMgr?'<td>'+(mg?esc(mg.name):'—')+'</td>':'')+'<td>'+x.sla.reasons.map(function(r){return esc(r.txt)}).join('<br>')+'</td><td><b style="color:#A50E0E">'+FV.left(x.sla.reasons[0].over)+'</b></td>'+(withMgr?'':'<td><button class="btn out sm" data-remind="'+x.id+'">Remind</button></td>')+'</tr>'}).join('')};
FV.teamView=function(tb,staff,redraw){var ST=window.ST,esc=BA.esc,isM=staff.role==='dsm',mgrs=FV.dir().filter(function(m){return m.role==='dsm'}),mid=isM?staff.id:(BA.ls('ba3_mgrsel')||(mgrs[0]||{}).id),me=FV.get(mid);
 if(!me){tb.innerHTML=ST.panel('Field team','<p style="color:var(--mute)">No District Sales Manager account found.</p>');return}
 var team=FV.team(mid),ids=team.map(function(m){return m.id}),items=[];ids.forEach(function(i){items=items.concat(FV.mine(i))});var open=items.filter(function(x){return !x.a.sub&&!x.a.fin}),c=FV.counts(open),fg=FV.flagged(function(e){return ids.indexOf(e.id)>-1}),wait=items.filter(function(x){return x.a.sub&&!x.a.fin}).length;
 tb.innerHTML=(isM?'':'<div style="margin-bottom:12px"><select id="mgs" class="cs" style="color:var(--ink)">'+mgrs.map(function(m){return '<option value="'+m.id+'"'+(m.id===mid?' selected':'')+'>'+esc(m.name)+' · '+esc(m.state)+'</option>'}).join('')+'</select></div>')+
 '<div class="kpis">'+ST.kpi('Field engineers',team.length,esc(me.state)+' · '+team.filter(function(m){return m.status==='active'}).length+' active')+ST.kpi('Open site visits',open.length,'')+'<div class="kpi" style="border-left:6px solid '+(c.urgent?FV.COL.urgent.bd:'#e3e3e8')+'"><small>Urgent</small><b>'+c.urgent+'</b><span>Deadline within 6 hours</span></div><div class="kpi" style="border-left:6px solid '+(c.overdue?FV.COL.overdue.bd:'#e3e3e8')+';'+(c.overdue?'background:'+FV.COL.overdue.bg:'')+'"><small>Overdue</small><b style="'+(c.overdue?'color:'+FV.COL.overdue.tx:'')+'">'+c.overdue+'</b><span>Needs your attention</span></div></div>'+
 ST.panel('Escalations from your team ('+fg.length+')','<p style="color:var(--mute);margin:0 0 10px;font-size:13px">A visit shows here when it was not accepted within 18 hours, not scheduled, or not completed within 48 hours of assignment. Admin and Leadership see the same list.</p>'+ST.table(['Property','Field engineer','What is late','Late by',''],[FV.escRows(fg,false)].filter(Boolean)))+
 ST.panel('My field team',ST.table(['Engineer','Cities','Mobile','Open','Urgent','Overdue','With checker','Status'],team.map(function(m){var mine=FV.mine(m.id),cc=FV.counts(mine.filter(function(x){return !x.a.sub&&!x.a.fin}));return '<tr><td><div style="display:flex;gap:8px;align-items:center">'+FV.avatar(m,30)+'<b>'+esc(m.name)+'</b></div></td><td>'+m.cities.map(FV.cl).map(esc).join(', ')+'</td><td>'+FV.tel(m.phone)+'</td><td>'+(cc.urgent+cc.overdue+cc.ok)+'</td><td>'+(cc.urgent?'<b style="color:#8A5A00">'+cc.urgent+'</b>':0)+'</td><td>'+(cc.overdue?'<b style="color:#A50E0E">'+cc.overdue+'</b>':0)+'</td><td>'+mine.filter(function(x){return x.a.sub&&!x.a.fin}).length+'</td><td>'+(m.status==='active'?ST.chip('Active','g'):m.status==='suspended'?ST.chip('Suspended','a'):ST.chip('Deactivated','r'))+'</td></tr>'}))+'<p style="color:var(--mute);font-size:13px;margin:10px 0 0">To change who reports to you, ask Admin (Staff, Reports to).</p>')+
 ST.panel('Alerts for you',ST.table(['When','Alert'],FV.notifs('mgr:'+mid).slice(0,10).map(function(n){return '<tr><td style="white-space:nowrap">'+ST.ago(n.at)+'</td><td>'+(n.sev==='red'?'<span style="color:#A50E0E">●</span> ':'')+esc(n.text)+'</td></tr>'})));
 if($('mgs'))$('mgs').onchange=function(){BA.ls('ba3_mgrsel',this.value);redraw()};
 function $(i){return document.getElementById(i)}
 tb.onclick=function(e){var b=e.target.closest('[data-remind]');if(!b)return;var id=b.dataset.remind,a=FV.asg()[id],p=FV.property(id);FV.notify(null,{type:'nudge',prop:id,eng:a.eng,to:['eng:'+a.eng],sev:'amber',text:'Reminder from '+me.name+': '+p.short+', '+p.loc+' is late. Please update it today.'});BA.toast('Reminder sent to '+FV.get(a.eng).name)}};
FV.leadPanel=function(){var ST=window.ST,esc=BA.esc,A=FV.asg(),rows=FV.STATES.map(function(st){var ids=FV.dir().filter(function(m){return m.role==='field'&&m.state===st}).map(function(m){return m.id}),it=[];ids.forEach(function(i){it=it.concat(FV.mine(i))});var op=it.filter(function(x){return !x.a.sub&&!x.a.fin}),c=FV.counts(op),ns=op.filter(function(x){return FV.sla(x.a).reasons.some(function(r){return r.t==='nosch'})}).length;return {st:st,eng:ids.length,open:op.length,u:c.urgent,o:c.overdue,ns:ns,w:it.filter(function(x){return x.a.sub&&!x.a.fin}).length,ok:it.filter(function(x){return x.a.fin}).length}}),fg=FV.flagged();
 return ST.panel('Field verification: deadlines','<div class="three" style="margin-bottom:14px"><div class="kpi" style="border-left:6px solid '+FV.COL.overdue.bd+'"><small>Overdue visits</small><b>'+rows.reduce(function(a,r){return a+r.o},0)+'</b><span>Not accepted in 18 h, or not done in 48 h</span></div><div class="kpi" style="border-left:6px solid '+FV.COL.urgent.bd+'"><small>Urgent</small><b>'+rows.reduce(function(a,r){return a+r.u},0)+'</b><span>Deadline within 6 hours</span></div><div class="kpi" style="border-left:6px solid '+FV.COL.overdue.bd+'"><small>Visit not scheduled</small><b>'+rows.reduce(function(a,r){return a+r.ns},0)+'</b><span>Accepted but no time booked</span></div></div>'+
 ST.table(['State','Engineers','Open','Urgent','Overdue','Not scheduled','With checker','Published'],rows.map(function(r){return '<tr><td><b>'+esc(r.st)+'</b></td><td>'+r.eng+'</td><td>'+r.open+'</td><td>'+(r.u?'<b style="color:#8A5A00">'+r.u+'</b>':0)+'</td><td>'+(r.o?'<b style="color:#A50E0E">'+r.o+'</b>':0)+'</td><td>'+(r.ns?'<b style="color:#A50E0E">'+r.ns+'</b>':0)+'</td><td>'+r.w+'</td><td>'+r.ok+'</td></tr>'}))+
 '<h3 style="font:800 15px var(--f);margin:16px 0 8px">Escalated now ('+fg.length+')</h3>'+ST.table(['Property','Field engineer','Reports to','What is late','Late by'],[FV.escRows(fg.slice(0,8),true)].filter(Boolean)))};
})();
